"""Create an offline-ready Olist dashboard from verified report tables."""
from pathlib import Path
import json
import pandas as pd
import sqlite3
ROOT=Path(__file__).resolve().parents[1]; R=ROOT/'reports'
summary=(R/'analysis_summary.md').read_text(encoding='utf-8-sig')
def table(name): return pd.read_csv(R/f'{name}.csv').to_dict(orient='records')
data={k:table(k) for k in ['monthly_sales','category_sales','top_products','state_sales','payment_methods','review_distribution','delivery_review','category_delivery']}
with sqlite3.connect(ROOT/"data"/"processed"/"olist_analytics.db") as con:
    revenue, orders = con.execute("SELECT SUM(i.price), COUNT(DISTINCT o.order_id) FROM fact_orders o JOIN fact_order_items i USING(order_id) WHERE o.order_status=?", ("delivered",)).fetchone()
    delivery, late_rate = con.execute("SELECT AVG(delivery_days), AVG(CASE WHEN delivery_late=1 THEN 1.0 ELSE 0.0 END) FROM fact_orders WHERE order_status=? AND delivery_days IS NOT NULL AND delivery_late IS NOT NULL", ("delivered",)).fetchone()
    review = con.execute("SELECT AVG(avg_review_score) FROM fact_reviews_by_order").fetchone()[0]
    repeat, buyers = con.execute("SELECT SUM(CASE WHEN n>1 THEN 1 ELSE 0 END), COUNT(*) FROM (SELECT customer_unique_id, COUNT(DISTINCT order_id) n FROM fact_orders GROUP BY customer_unique_id)").fetchone()
    review_rows = con.execute("SELECT COUNT(*) FROM fact_reviews").fetchone()[0]
metrics={"revenue":round(revenue,2),"orders":orders,"aov":round(revenue/orders,2),"delivery":round(delivery,2),"late":f"{late_rate:.1%}","review":round(review,2),"repeat":f"{repeat/buyers:.1%}","review_rows":review_rows}
payload=json.dumps(data,ensure_ascii=False).replace('</','<\\/')
metrics_json=json.dumps(metrics)
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Olist | Business Intelligence</title><style>
:root{--ink:#172438;--muted:#68788d;--line:#e6ebf2;--blue:#3273e8;--teal:#1ca485;--bg:#f5f7fb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 Segoe UI,Arial,sans-serif}.wrap{max-width:1280px;padding:30px 26px 45px;margin:auto}.top{display:flex;justify-content:space-between;align-items:end;gap:20px}.tag{font-size:11px;color:var(--blue);font-weight:800;letter-spacing:.12em;text-transform:uppercase}.top h1{font-size:30px;letter-spacing:-.04em;margin:3px 0}.muted{color:var(--muted);margin:0}.nav{display:flex;gap:8px;margin:22px 0 15px;flex-wrap:wrap}.nav button{border:1px solid var(--line);background:white;color:var(--muted);padding:9px 15px;border-radius:999px;font-weight:650;cursor:pointer}.nav button.active{background:var(--ink);color:white;border-color:var(--ink)}.page{display:none}.page.active{display:block}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.card,.panel{background:#fff;border:1px solid var(--line);border-radius:15px;box-shadow:0 5px 22px #1c345608}.card{padding:16px 19px}.label{font-size:12px;color:var(--muted)}.value{font-size:25px;font-weight:760;letter-spacing:-.035em;margin-top:6px}.panel{padding:19px;margin-top:14px}.panel h2{font-size:16px;margin:0 0 13px}.cols{display:grid;grid-template-columns:1fr 1fr;gap:14px}.bars{display:grid;gap:10px}.row{display:grid;grid-template-columns:minmax(85px,1fr) 2.2fr auto;align-items:center;gap:10px;font-size:12px}.name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.track{height:9px;background:#eef2f8;border-radius:9px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,var(--blue),#77a3fb);border-radius:8px}.num{text-align:right;font-variant-numeric:tabular-nums;color:#45546a}.months{display:flex;align-items:end;height:225px;gap:9px;border-bottom:1px solid var(--line);padding:6px 3px}.month{height:100%;flex:1;min-width:0;display:flex;align-items:center;justify-content:end;flex-direction:column;gap:8px}.stick{width:min(34px,80%);min-height:4px;background:linear-gradient(180deg,#72a2ff,var(--blue));border-radius:6px 6px 1px 1px}.month span{font-size:10px;color:var(--muted)}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:9px 8px;border-bottom:1px solid var(--line)}th{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}.footer{font-size:11px;color:var(--muted);margin:16px 2px}.print{border:0;background:var(--blue);color:white;border-radius:9px;padding:9px 13px;cursor:pointer}@media(max-width:850px){.grid{grid-template-columns:repeat(2,1fr)}.cols{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}}@media(max-width:480px){.wrap{padding:20px 13px}.value{font-size:21px}.row{grid-template-columns:78px 1fr auto;gap:7px}}
</style></head><body><main class="wrap"><header class="top"><div><div class="tag">Olist · Brazil · 2016–2018</div><h1>E-Commerce Business Intelligence</h1><p class="muted">Sales, customer, delivery and satisfaction performance from the supplied marketplace data.</p></div><button class="print" onclick="window.print()">Print / Save PDF</button></header>
<nav class="nav"><button class="active" data-page="overview">Executive Overview</button><button data-page="sales">Sales & Products</button><button data-page="customers">Customers</button><button data-page="experience">Delivery & Experience</button></nav>
<section class="page active" id="overview"><div class="grid" id="kpis"></div><div class="panel"><h2>Monthly product-price revenue · delivered orders</h2><div class="months" id="monthly"></div></div><div class="cols"><div class="panel"><h2>Leading categories</h2><div class="bars" id="topcats"></div></div><div class="panel"><h2>Revenue by customer state</h2><div class="bars" id="statesmini"></div></div></div></section>
<section class="page" id="sales"><div class="cols"><div class="panel"><h2>Category product revenue</h2><div class="bars" id="categories"></div></div><div class="panel"><h2>Top products</h2><div class="bars" id="products"></div></div></div><div class="panel"><h2>Monthly delivered product revenue and orders</h2><div class="tablewrap"><table><thead><tr><th>Month</th><th>Product revenue</th><th>Orders</th></tr></thead><tbody id="monthlytable"></tbody></table></div></div></section>
<section class="page" id="customers"><div class="panel"><h2>Customer-state footprint · top 15 by product revenue</h2><div class="bars" id="states"></div></div><div class="panel"><h2>State detail</h2><table><thead><tr><th>State</th><th>Product revenue</th><th>Orders</th><th>Identified customers</th></tr></thead><tbody id="statetable"></tbody></table></div></section>
<section class="page" id="experience"><div class="cols"><div class="panel"><h2>Delivery result and review score</h2><div id="delivery"></div></div><div class="panel"><h2>Review score distribution · order-level</h2><div class="bars" id="reviews"></div></div></div><div class="cols"><div class="panel"><h2>Payment method</h2><div class="bars" id="payments"></div></div><div class="panel"><h2>Average delivery days by category</h2><div class="bars" id="categorydelivery"></div></div></div></section>
<p class="footer">Product revenue sums order-item price and excludes freight. Payment value is a separate measure. Late rate uses delivered orders with defined dates. Customer repeat rate uses customer_unique_id. This historical data supports descriptive comparisons, not causal claims.</p></main>
<script>const D=PAYLOAD,M=METRICS,usd=n=>'R$ '+Number(n).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}),num=n=>Number(n).toLocaleString('en-US');document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button,.page').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.page).classList.add('active')});document.getElementById('kpis').innerHTML=[['Product revenue',usd(M.revenue),'Delivered item prices'],['Delivered orders',num(M.orders),'Distinct delivered orders'],['Average order value',usd(M.aov),'Revenue / delivered orders'],['Average delivery',M.delivery+' days','Delivered orders with timestamps'],['Late delivery',M.late,'Defined delivered-order dates'],['Average review',M.review+' / 5','Order-weighted average'],['Repeat buyers',M.repeat,'Unique customer IDs with >1 order'],['Review records',num(M.review_rows),'Supplied review rows']].map(x=>`<article class="card"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="label">${x[2]}</div></article>`).join('');function bars(id,arr,key,label,limit=12){let a=arr.slice(0,limit),max=Math.max(1,...a.map(x=>+x[key]));document.getElementById(id).innerHTML=a.map(x=>`<div class="row"><div class="name" title="${x.category||x.state||x.product_id||x.payment_type||x.review_score}">${x.category||x.state||x.product_id||x.payment_type||x.review_score}</div><div class="track"><div class="fill" style="width:${Math.max(2,+x[key]/max*100)}%"></div></div><div class="num">${label(+x[key])}</div></div>`).join('')||'<span class="muted">No rows</span>'}bars('topcats',D.category_sales,'product_revenue',usd,8);bars('categories',D.category_sales,'product_revenue',usd,25);bars('products',D.top_products,'product_revenue',usd,15);bars('statesmini',D.state_sales,'product_revenue',usd,8);bars('states',D.state_sales,'product_revenue',usd,15);bars('payments',D.payment_methods,'recorded_payment_value',usd,10);bars('reviews',D.review_distribution,'orders',num,5);bars('categorydelivery',[...D.category_delivery].sort((a,b)=>b.avg_delivery_days-a.avg_delivery_days),'avg_delivery_days',n=>n.toFixed(1)+' d',10);let mx=Math.max(...D.monthly_sales.map(x=>+x.product_revenue));document.getElementById('monthly').innerHTML=D.monthly_sales.map(x=>`<div class="month" title="${x.month}: ${usd(x.product_revenue)}"><div class="stick" style="height:${Math.max(2,x.product_revenue/mx*100)}%"></div><span>${x.month.slice(2)}</span></div>`).join('');document.getElementById('monthlytable').innerHTML=D.monthly_sales.map(x=>`<tr><td>${x.month}</td><td>${usd(x.product_revenue)}</td><td>${num(x.orders)}</td></tr>`).join('');document.getElementById('statetable').innerHTML=D.state_sales.slice(0,15).map(x=>`<tr><td>${x.state}</td><td>${usd(x.product_revenue)}</td><td>${num(x.orders)}</td><td>${num(x.customers)}</td></tr>`).join('');document.getElementById('delivery').innerHTML=D.delivery_review.map(x=>`<p><b>${x.delivery_result}</b>: ${x.avg_review_score??'—'} / 5 average review · ${num(x.orders)} orders</p>`).join('');</script></body></html>'''
html=html.replace('PAYLOAD',payload).replace('METRICS',metrics_json)
(R/'dashboard.html').write_text(html,encoding='utf-8')
print('Wrote',R/'dashboard.html')
